protocol Box {
    associatedtype Content
    var content: Content { get }
}

struct GiftBox: Box {
    let content: String
}

let box = GiftBox(content: "Teddy Bear")
print(box.content)

protocol QueueProtocol {
    associatedtype Element
    mutating func push(_ item: Element)
    mutating func pop() -> Element?
}

struct IntQueue: QueueProtocol {
    var items: [Int] = []
    mutating func push(_ item: Int) { items.append(item) }
    mutating func pop() -> Int? { items.isEmpty ? nil : items.removeFirst() }
}

var queue = IntQueue()
queue.push(10)
queue.push(20)
print(queue.pop() ?? 0)

protocol Summable {
    associatedtype Value: Numeric
    var values: [Value] { get }
}

extension Summable {
    func total() -> Value {
        return values.reduce(0, +)
    }
}

struct Stats: Summable {
    let values: [Int]
}

let stats = Stats(values: [1, 2, 3, 4])
print(stats.total())

protocol PairContainer {
    associatedtype First
    associatedtype Second
    var first: First { get }
    var second: Second { get }
}

extension PairContainer where First == Second {
    func areIdentical() -> String {
        return "Matching Types"
    }
}

struct IdenticalPair<T>: PairContainer {
    let first: T
    let second: T
}

let pair = IdenticalPair(first: "Apple", second: "Banana")
print(pair.areIdentical())

protocol SequenceHolder {
    associatedtype Item
    var items: [Item] { get }
}

func compareFirstElements<S1: SequenceHolder, S2: SequenceHolder>(_ a: S1, _ b: S2) -> Bool
where S1.Item == S2.Item, S1.Item: Equatable {
    guard let firstA = a.items.first, let firstB = b.items.first else {
        return false
    }
    return firstA == firstB
}

struct Holder<T>: SequenceHolder {
    let items: [T]
}

let h1 = Holder(items: [100, 200])
let h2 = Holder(items: [100, 300])
print(compareFirstElements(h1, h2))

protocol Transformable {
    associatedtype Input
    associatedtype Output = String
    func transform(_ input: Input) -> Output
}

struct IntStringifier: Transformable {
    func transform(_ input: Int) -> String {
        return "Number: \(input)"
    }
}

let transformer = IntStringifier()
print(transformer.transform(7))

protocol Stash {
    associatedtype Value
    var storage: [Value] { get }
}

extension Stash where Value: Collection {
    func totalCount() -> Int {
        return storage.reduce(0) { $0 + $1.count }
    }
}

struct GroupedWords: Stash {
    let storage: [[String]]
}

let group = GroupedWords(storage: [["a", "b"], ["c", "d", "e"]])
print(group.totalCount())

protocol PrintableValue {
    associatedtype T
    func display() -> String
}

extension PrintableValue where T: CustomStringConvertible {
    func formatted() -> String {
        return "Formatted: \(display())"
    }
}

struct Label: PrintableValue {
    typealias T = String
    let text: String
    func display() -> String { text }
}

let label = Label(text: "Swift 6")
print(label.formatted())

